//! Isogenies from a kernel of smooth prime-power order l^n generated by one point P:
//! a chain of l-isogenies (De Feo–Jao–Plût 2014, Costello–Longa–Naehrig 2016 "strategies").
//!
//! `run(E, P, n, extra)` computes the n-step chain with kernel <P> and pushes the points in `extra`
//! through it. Choose k in 1..n: the first k steps have kernel <[l^{n-k}]P>; P itself (and the
//! extras) are pushed through them, giving the generator phi_1(P) of order l^{n-k} for the rest.
//!   Naive:    k = 1 (one step at a time; O(n^2) l-multiplications, no extra pushing)
//!   Balanced: k = n/2 (O(n log n) multiplications and pushes)
//!   Optimal:  k minimising a cost model  C(n, m) = min_k  n*mul + C(k, m+1) + C(n-k, m)
//!             with C(1, m) = iso + m*eval  (m = number of points that must be pushed)
use crate::curve::*;
use crate::field::Field;
use crate::kernel::velu::velu_cyclic;

#[derive(Clone, Copy, Debug)]
pub enum Strategy {
    Naive,
    Balanced,
    /// Costs of one multiplication by l, one point evaluation, one l-isogeny construction.
    Optimal {
        mul: f64,
        eval: f64,
        iso: f64,
    },
}

#[derive(Clone, Copy, Debug, Default)]
pub struct ChainStats {
    pub l_mults: usize,
    pub evals: usize,
    pub builds: usize,
}

pub struct IsogenyChain<F: Field> {
    pub steps: Vec<Box<dyn Isogeny<F>>>,
    pub dom: Curve<F::E>,
    pub cod: Curve<F::E>,
    pub deg: u64,
}

impl<F: Field> Isogeny<F> for IsogenyChain<F> {
    fn domain(&self) -> &Curve<F::E> {
        &self.dom
    }
    fn codomain(&self) -> &Curve<F::E> {
        &self.cod
    }
    fn degree(&self) -> u64 {
        self.deg
    }
    fn eval_x(&self, f: &F, x: F::E) -> Option<F::E> {
        // each step only uses y multiplicatively, so a formal y = 1 yields the x-map
        match self.eval(f, &Pt::Aff(x, f.one())) {
            Pt::Inf => None,
            Pt::Aff(x2, _) => Some(x2),
        }
    }
    fn eval(&self, f: &F, p: &Pt<F::E>) -> Pt<F::E> {
        let mut q = *p;
        for s in &self.steps {
            q = s.eval(f, &q);
        }
        q
    }
}

pub fn mul_by_ell<F: Field>(
    f: &F,
    e: &Curve<F::E>,
    p: &Pt<F::E>,
    ell: u64,
    times: usize,
    st: &mut ChainStats,
) -> Pt<F::E> {
    let mut q = *p;
    for _ in 0..times {
        q = pmul(f, e, &q, ell as u128);
        st.l_mults += 1;
    }
    q
}

/// Split table for the optimal strategy: best[n][m] = k.
fn optimal_table(nmax: usize, mul: f64, eval: f64, iso: f64) -> Vec<Vec<usize>> {
    let mmax = nmax + 1;
    let mut cost = vec![vec![0f64; mmax + 1]; nmax + 1];
    let mut best = vec![vec![1usize; mmax + 1]; nmax + 1];
    for m in 0..=mmax {
        cost[1][m] = iso + m as f64 * eval;
    }
    for n in 2..=nmax {
        for m in 0..=mmax {
            let mut bc = f64::INFINITY;
            for k in 1..n {
                let mp = (m + 1).min(mmax);
                let c = n as f64 * mul + cost[k][mp] + cost[n - k][m];
                if c < bc {
                    bc = c;
                    best[n][m] = k;
                }
            }
            cost[n][m] = bc;
        }
    }
    best
}

#[allow(clippy::too_many_arguments)]
fn run<F: Field>(
    f: &F,
    e: &Curve<F::E>,
    p: Pt<F::E>,
    n: usize,
    ell: u64,
    extra: Vec<Pt<F::E>>,
    strat: &Strategy,
    table: &[Vec<usize>],
    steps: &mut Vec<Box<dyn Isogeny<F>>>,
    st: &mut ChainStats,
) -> (Curve<F::E>, Vec<Pt<F::E>>) {
    if n == 0 {
        return (*e, extra);
    }
    if n == 1 {
        let iso = velu_cyclic(f, e, &p, ell);
        st.builds += 1;
        let pushed: Vec<_> = extra
            .iter()
            .map(|q| {
                st.evals += 1;
                iso.eval(f, q)
            })
            .collect();
        let cod = iso.cod;
        steps.push(Box::new(iso));
        return (cod, pushed);
    }
    let k = match strat {
        Strategy::Naive => 1,
        Strategy::Balanced => n / 2,
        Strategy::Optimal { .. } => table[n][extra.len().min(table[n].len() - 1)],
    };
    let p1 = mul_by_ell(f, e, &p, ell, n - k, st); // order l^k, kernel of the first block
    let mut ex = vec![p];
    ex.extend(extra);
    let (e1, ex1) = run(f, e, p1, k, ell, ex, strat, table, steps, st);
    let p2 = ex1[0]; // image of P: generator of order l^{n-k}
    run(
        f,
        &e1,
        p2,
        n - k,
        ell,
        ex1[1..].to_vec(),
        strat,
        table,
        steps,
        st,
    )
}

/// Compute the l^n-isogeny with kernel <P> (P of exact order l^n, l prime), pushing `push` through it.
pub fn ell_power_isogeny<F: Field>(
    f: &F,
    e: &Curve<F::E>,
    p: &Pt<F::E>,
    ell: u64,
    n: usize,
    push: &[Pt<F::E>],
    strat: Strategy,
) -> (IsogenyChain<F>, Vec<Pt<F::E>>, ChainStats) {
    let table = match strat {
        Strategy::Optimal { mul, eval, iso } => optimal_table(n.max(1), mul, eval, iso),
        _ => vec![],
    };
    let mut st = ChainStats::default();
    let mut steps = vec![];
    let (cod, pushed) = run(
        f,
        e,
        *p,
        n,
        ell,
        push.to_vec(),
        &strat,
        &table,
        &mut steps,
        &mut st,
    );
    let chain = IsogenyChain {
        steps,
        dom: *e,
        cod,
        deg: ell.pow(n as u32),
    };
    (chain, pushed, st)
}

/// Kernel of composite smooth order N = prod l_i^{n_i}: apply the prime-power chains one after the
/// other (the generator of the next stage is the pushed image of [l_i^{n_i}]P).
pub fn smooth_isogeny<F: Field>(
    f: &F,
    e: &Curve<F::E>,
    p: &Pt<F::E>,
    factors: &[(u64, usize)],
    strat: Strategy,
) -> (IsogenyChain<F>, ChainStats) {
    let mut cur_e = *e;
    let mut gen = *p;
    let mut all: Vec<Box<dyn Isogeny<F>>> = vec![];
    let mut total = ChainStats::default();
    let mut deg = 1u64;
    for (idx, &(ell, n)) in factors.iter().enumerate() {
        // kernel generator of this stage: the current generator (already pushed through the earlier
        // stages, so it has lost their prime-power parts) times the parts of the later stages
        let mut mult = 1u128;
        for &(l2, n2) in &factors[idx + 1..] {
            mult *= (l2 as u128).pow(n2 as u32);
        }
        let kgen = pmul(f, &cur_e, &gen, mult);
        let (chain, pushed, st) = ell_power_isogeny(f, &cur_e, &kgen, ell, n, &[gen], strat);
        total.l_mults += st.l_mults;
        total.evals += st.evals;
        total.builds += st.builds;
        deg *= chain.deg;
        cur_e = chain.cod;
        gen = pushed[0];
        all.extend(chain.steps);
    }
    (
        IsogenyChain {
            steps: all,
            dom: *e,
            cod: cur_e,
            deg,
        },
        total,
    )
}
